depthwise_conv_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

constexpr int BLOCK_W = 256;
constexpr int OH_TILE = 4;
constexpr int OW_TILE = 4; // vectorized 128-bit (float4) loads/stores across output width
constexpr int MAX_ROWS = 35; // supports K up to 32 with OH_TILE=4
__global__ void depthwise_conv2d_kh1_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int N, const int C, const int H, const int W,
    const int K,
    const int H_out, const int W_out,
    const int stride, const int padding, const int dilation,
    const bool has_bias)
{
    // blockIdx.z encodes the combined (n, c) index -> keeps grid small
    // blockIdx.y encodes the output row (oh)
    // blockIdx.x * blockDim.x + threadIdx.x encodes the output column (ow),
    // giving fully coalesced global memory accesses across threads since
    // consecutive threads read consecutive elements along the W dimension.
    int nc = blockIdx.z;
    int c = nc % C;
    int n = nc / C;
    int oh = blockIdx.y;
    int ow = blockIdx.x * blockDim.x + threadIdx.x;
    if (ow >= W_out) return;
    int iw = ow * stride - padding;
    float acc = 0.0f;
    if (iw >= 0 && iw < W) {
        const float* in_base = input + ((n * C + c) * H) * W + iw;
        const float* w_ptr = weight + c * K;
        int ih_base = oh * stride - padding;
        #pragma unroll
        for (int kh = 0; kh < K; ++kh) {
            int ih = ih_base + kh * dilation;
            if (ih >= 0 && ih < H) {
                acc += in_base[ih * W] * w_ptr[kh];
            }
        }
    }
    if (has_bias) {
        acc += bias[c];
    }
    output[((n * C + c) * H_out + oh) * W_out + ow] = acc;
}
// Register-blocked kernel: each thread computes OH_TILE consecutive output rows.
// Reusable input rows are staged into registers once (sliding window over the
// H dimension) instead of being reloaded from global memory for every output,
// which is the dominant source of redundant traffic in the naive kernel above.
// Only valid for stride == 1 && dilation == 1 (checked by the host launcher).
__global__ void depthwise_conv2d_kh1_tiled_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int N, const int C, const int H, const int W,
    const int K,
    const int H_out, const int W_out,
    const int padding,
    const bool has_bias)
{
    int nc = blockIdx.z;
    int c = nc % C;
    int n = nc / C;
    int oh_start = blockIdx.y * OH_TILE;
    int ow_start = (blockIdx.x * blockDim.x + threadIdx.x) * OW_TILE;
    if (ow_start >= W_out) return;
    const float* in_base = input + ((n * C + c) * H) * W;
    const float* w_ptr = weight + c * K;
    int total_rows = K + OH_TILE - 1;
    float rows[MAX_ROWS][OW_TILE];
    #pragma unroll
    for (int s = 0; s < MAX_ROWS; ++s) {
        if (s < total_rows) {
            int ih = oh_start - padding + s;
            bool row_valid = (ih >= 0 && ih < H);
            int iw0 = ow_start - padding;
            if (row_valid && iw0 >= 0 && (iw0 + OW_TILE) <= W &&
                (((size_t)(in_base + ih * W + iw0)) % 16 == 0)) {
                float4 v = __ldg(reinterpret_cast<const float4*>(in_base + ih * W + iw0));
                rows[s][0] = v.x;
                rows[s][1] = v.y;
                rows[s][2] = v.z;
                rows[s][3] = v.w;
            } else {
                #pragma unroll
                for (int t = 0; t < OW_TILE; ++t) {
                    int iw = iw0 + t;
                    if (row_valid && iw >= 0 && iw < W) {
                        rows[s][t] = in_base[ih * W + iw];
                    } else {
                        rows[s][t] = 0.0f;
                    }
                }
            }
        }
    }
    float acc[OH_TILE][OW_TILE];
    #pragma unroll
    for (int t = 0; t < OH_TILE; ++t) {
        #pragma unroll
        for (int u = 0; u < OW_TILE; ++u) {
            acc[t][u] = 0.0f;
        }
    }
    for (int kh = 0; kh < K; ++kh) {
        float wv = w_ptr[kh];
        #pragma unroll
        for (int t = 0; t < OH_TILE; ++t) {
            #pragma unroll
            for (int u = 0; u < OW_TILE; ++u) {
                acc[t][u] += rows[t + kh][u] * wv;
            }
        }
    }
    if (has_bias) {
        float b = bias[c];
        #pragma unroll
        for (int t = 0; t < OH_TILE; ++t) {
            #pragma unroll
            for (int u = 0; u < OW_TILE; ++u) {
                acc[t][u] += b;
            }
        }
    }
    #pragma unroll
    for (int t = 0; t < OH_TILE; ++t) {
        int oh = oh_start + t;
        if (oh < H_out) {
            float* out_row = output + ((n * C + c) * H_out + oh) * W_out + ow_start;
            if ((ow_start + OW_TILE) <= W_out &&
                (((size_t)out_row) % 16 == 0)) {
                float4 v = make_float4(acc[t][0], acc[t][1], acc[t][2], acc[t][3]);
                *reinterpret_cast<float4*>(out_row) = v;
            } else {
                #pragma unroll
                for (int u = 0; u < OW_TILE; ++u) {
                    int ow = ow_start + u;
                    if (ow < W_out) {
                        out_row[u] = acc[t][u];
                    }
                }
            }
        }
    }
}
template<int KSIZE>
__global__ void depthwise_conv2d_kh1_tiled_kernel_t(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int N, const int C, const int H, const int W,
    const int H_out, const int W_out,
    const int padding,
    const bool has_bias)
{
    constexpr int TOTAL_ROWS = KSIZE + OH_TILE - 1;
    int nc = blockIdx.z;
    int c = nc % C;
    int n = nc / C;
    int oh_start = blockIdx.y * OH_TILE;
    int ow_start = (blockIdx.x * blockDim.x + threadIdx.x) * OW_TILE;
    if (ow_start >= W_out) return;
    const float* in_base = input + ((n * C + c) * H) * W;
    const float* w_ptr = weight + c * KSIZE;
    float rows[TOTAL_ROWS][OW_TILE];
    #pragma unroll
    for (int s = 0; s < TOTAL_ROWS; ++s) {
        int ih = oh_start - padding + s;
        bool row_valid = (ih >= 0 && ih < H);
        int iw0 = ow_start - padding;
        if (row_valid && iw0 >= 0 && (iw0 + OW_TILE) <= W &&
            (((size_t)(in_base + ih * W + iw0)) % 16 == 0)) {
            float4 v = __ldg(reinterpret_cast<const float4*>(in_base + ih * W + iw0));
            rows[s][0] = v.x;
            rows[s][1] = v.y;
            rows[s][2] = v.z;
            rows[s][3] = v.w;
        } else {
            #pragma unroll
            for (int t = 0; t < OW_TILE; ++t) {
                int iw = iw0 + t;
                rows[s][t] = (row_valid && iw >= 0 && iw < W) ? in_base[ih * W + iw] : 0.0f;
            }
        }
    }
    float acc[OH_TILE][OW_TILE];
    #pragma unroll
    for (int t = 0; t < OH_TILE; ++t) {
        #pragma unroll
        for (int u = 0; u < OW_TILE; ++u) {
            acc[t][u] = 0.0f;
        }
    }
    #pragma unroll
    for (int kh = 0; kh < KSIZE; ++kh) {
        float wv = w_ptr[kh];
        #pragma unroll
        for (int t = 0; t < OH_TILE; ++t) {
            #pragma unroll
            for (int u = 0; u < OW_TILE; ++u) {
                acc[t][u] += rows[t + kh][u] * wv;
            }
        }
    }
    if (has_bias) {
        float b = bias[c];
        #pragma unroll
        for (int t = 0; t < OH_TILE; ++t) {
            #pragma unroll
            for (int u = 0; u < OW_TILE; ++u) {
                acc[t][u] += b;
            }
        }
    }
    #pragma unroll
    for (int t = 0; t < OH_TILE; ++t) {
        int oh = oh_start + t;
        if (oh < H_out) {
            float* out_row = output + ((n * C + c) * H_out + oh) * W_out + ow_start;
            if ((ow_start + OW_TILE) <= W_out &&
                (((size_t)out_row) % 16 == 0)) {
                float4 v = make_float4(acc[t][0], acc[t][1], acc[t][2], acc[t][3]);
                *reinterpret_cast<float4*>(out_row) = v;
            } else {
                #pragma unroll
                for (int u = 0; u < OW_TILE; ++u) {
                    int ow = ow_start + u;
                    if (ow < W_out) {
                        out_row[u] = acc[t][u];
                    }
                }
            }
        }
    }
}
torch::Tensor depthwise_conv2d_kh1_cuda(
