    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    bool has_bias)
{
    input = input.contiguous();
    weight = weight.contiguous();
    const int N = input.size(0);
    const int C = input.size(1);
    const int H = input.size(2);
    const int W = input.size(3);
    const int K = weight.size(2); // weight shape: (C, 1, K, 1)
    const int H_out = (H + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    const int W_out = (W + 2 * padding - dilation * (1 - 1) - 1) / stride + 1;
    auto output = torch::empty({N, C, H_out, W_out}, input.options());
    const float* bias_ptr = nullptr;
    if (has_bias) {
        bias = bias.contiguous();
        bias_ptr = bias.data_ptr<float>();
    }
    dim3 block(BLOCK_W);
    bool can_tile = (stride == 1 && dilation == 1 && (K + OH_TILE - 1) <= MAX_ROWS);
    if (can_tile) {
        int num_ow_tiles = (W_out + OW_TILE - 1) / OW_TILE;
        dim3 grid((unsigned int)((num_ow_tiles + BLOCK_W - 1) / BLOCK_W),
                  (unsigned int)((H_out + OH_TILE - 1) / OH_TILE),
                  (unsigned int)(N * C));
        switch (K) {
            case 1:
                depthwise_conv2d_kh1_tiled_kernel_t<1><<<grid, block>>>(
                    input.data_ptr<float>(), weight.data_ptr<float>(), bias_ptr,
                    output.data_ptr<float>(), N, C, H, W, H_out, W_out, padding, has_bias);
                break;
            case 2:
                depthwise_conv2d_kh1_tiled_kernel_t<2><<<grid, block>>>(
                    input.data_ptr<float>(), weight.data_ptr<float>(), bias_ptr,
                    output.data_ptr<float>(), N, C, H, W, H_out, W_out, padding, has_bias);
                break;
            case 3:
                depthwise_conv2d_kh1_tiled_kernel_t<3><<<grid, block>>>(
                    input.data_ptr<float>(), weight.data_ptr<float>(), bias_ptr,
                    output.data_ptr<float>(), N, C, H, W, H_out, W_out, padding, has_bias);
                break;
            case 4:
                depthwise_conv2d_kh1_tiled_kernel_t<4><<<grid, block>>>(
                    input.data_ptr<float>(), weight.data_ptr<float>(), bias_ptr,
                    output.data_ptr<float>(), N, C, H, W, H_out, W_out, padding, has_bias);
                break;
            case 5:
                depthwise_conv2d_kh1_tiled_kernel_t<5><<<grid, block>>>(
                    input.data_ptr<float>(), weight.data_ptr<float>(), bias_ptr,
                    output.data_ptr<float>(), N, C, H, W, H_out, W_out, padding, has_bias);
                break;
            case 6:
                depthwise_conv2d_kh1_tiled_kernel_t<6><<<grid, block>>>(
                    input.data_ptr<float>(), weight.data_ptr<float>(), bias_ptr,
                    output.data_ptr<float>(), N, C, H, W, H_out, W_out, padding, has_bias);
                break;
            case 7:
                depthwise_conv2d_kh1_tiled_kernel_t<7><<<grid, block>>>(
                    input.data_ptr<float>(), weight.data_ptr<float>(), bias_ptr,
                    output.data_ptr<float>(), N, C, H, W, H_out, W_out, padding, has_bias);
                break;
            case 8:
                depthwise_conv2d_kh1_tiled_kernel_t<8><<<grid, block>>>(
                    input.data_ptr<float>(), weight.data_ptr<float>(), bias_ptr,
                    output.data_ptr<float>(), N, C, H, W, H_out, W_out, padding, has_bias);
                break;
            case 9:
                depthwise_conv2d_kh1_tiled_kernel_t<9><<<grid, block>>>(
                    input.data_ptr<float>(), weight.data_ptr<float>(), bias_ptr,
                    output.data_ptr<float>(), N, C, H, W, H_out, W_out, padding, has_bias);
                break;
            case 10:
                depthwise_conv2d_kh1_tiled_kernel_t<10><<<grid, block>>>(
                    input.data_ptr<float>(), weight.data_ptr<float>(), bias_ptr,
                    output.data_ptr<float>(), N, C, H, W, H_out, W_out, padding, has_bias);
                break;
            case 11:
                depthwise_conv2d_kh1_tiled_kernel_t<11><<<grid, block>>>(
                    input.data_ptr<float>(), weight.data_ptr<float>(), bias_ptr,
                    output.data_ptr<float>(), N, C, H, W, H_out, W_out, padding, has_bias);
                break;
            default:
                depthwise_conv2d_kh1_tiled_kernel<<<grid, block>>>(
                    input.data_ptr<float>(),
                    weight.data_ptr<float>(),
                    bias_ptr,
                    output.data_ptr<float>(),
                    N, C, H, W,
                    K,
                    H_out, W_out,
                    padding,
                    has_bias
                );
                break;
        }
    } else {
        dim3 grid((unsigned int)((W_out + BLOCK_W - 1) / BLOCK_W),
                  (unsigned int)H_out,
                  (unsigned int)(N * C));
        depthwise_conv2d_kh1_kernel<<<grid, block>>>(
            input.data_ptr<float>(),
            weight.data_ptr<float>(),
            bias_ptr,
            output.data_ptr<float>(),
            N, C, H, W,
            K,
            H_out, W_out,
            stride, padding, dilation,
            has_bias
        );
    }
    return output;
}
