class ModelNew(nn.Module):
    """
    Performs a depthwise 2D convolution with a square input and an asymmetric
    kernel (kernel_size, 1), implemented with a custom fused CUDA kernel.
    """
    def __init__(self, in_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.has_bias = bias

        # Match parameter shapes of nn.Conv2d with groups=in_channels
        self.weight = nn.Parameter(torch.empty(in_channels, 1, kernel_size, 1))
        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)

        if bias:
            self.bias = nn.Parameter(torch.empty(in_channels))
            fan_in = kernel_size
            bound = 1 / (fan_in ** 0.5)
            nn.init.uniform_(self.bias, -bound, bound)
        else:
            self.register_parameter('bias', None)

        self.conv_op = depthwise_conv_module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous()
        bias_tensor = self.bias if self.has_bias else torch.empty(0, device=x.device, dtype=x.dtype)
        return self.conv_op.depthwise_conv2d_kh1_cuda(
            x, self.weight, bias_tensor,
            self.stride, self.padding, self.dilation, self.has_bias
        )


